def is_bored(S):
    sentences = S.split('.')
    total_boredoms = 0
    for sentence in sentences:
        parts = sentence.split('?')
        for part in parts:
            subparts = part.split('!')
            for subpart in subparts:
                if subpart.strip().startswith('I '):
                    total_boredoms += 1
    return total_boredoms
